begin;

with input_items as (
  select *
  from jsonb_to_recordset($seed_json$[]$seed_json$::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    aliases text[],
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.aliases, '{}'::text[]) as aliases,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, aliases, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, aliases, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  aliases = excluded.aliases,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset($seed_json$[{"id": "27db6459-1aab-5541-af83-118bcb9fc6fc", "feature_slug": "feature-guide-writing", "title": "Writing Principles (Feature Guide Specific)", "content": "### Progressive Disclosure\n\nSections 1-2 are human-readable with natural prose — they orient the reader. Sections 3-8 are dense and structured (tables, bullets, numbered steps). Minimize prose in later sections.\n\n### Concrete Logic Over Fluffy Statements\n\nDefault to describing specific system behavior — what triggers, what matches, what the user sees. Reserve broad statements for the Marketing perspective (6b) where positioning language is the point.\n\n| Fluffy | Concrete |\n|---|---|\n| \"Powerful dynamic pricing engine\" | \"Matching engine evaluates 4 dimensions (tier, user type, persona, tags) and picks the highest-specificity match\" |\n| \"Seamless real-time redemption experience\" | \"Member taps Redeem → gets event_id immediately → result arrives via Realtime subscription within seconds\" |\n\n### Specificity Over Vagueness\n\nEvery vague phrase can be replaced with a specific one. The specific version always wins.\n\n| Vague | Specific |\n|---|---|\n| \"Supports multiple fulfillment methods\" | \"Four methods: digital, shipping, pickup, printed\" |\n| \"Flexible pricing\" | \"Points cost varies by tier, persona, and tags via 4-dimension matching\" |\n| \"Real-time processing\" | \"Async: member gets event_id immediately, result arrives via Realtime within seconds\" |\n\n### Anti-AI Voice\n\nNo filler words or phrases: \"comprehensive,\" \"robust,\" \"seamless,\" \"cutting-edge,\" \"it's important to note that,\" \"in order to,\" \"leverage.\" If a sentence still communicates value after removing the modifier, the modifier was filler.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["customer_success", "general", "product"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/FEATURE_GUIDE_WRITING_PRINCIPLES.md#writing-principles-feature-guide-specific", "metadata": {"genre": "feature_guide", "source_file": "FEATURE_GUIDE_WRITING_PRINCIPLES.md", "section_anchor": "writing-principles-feature-guide-specific", "feature_slug": "feature-guide-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "ea63611accfcc65307694e7d6e9070ec447e369fce87d257cff9c55748c20682", "truncated": false}, "is_active": true}, {"id": "0dea5e5d-eace-5dad-8af5-885bb4f81db8", "feature_slug": "proposal-writing", "title": "Proposal Quality Checklist", "content": "### Reading (when responding to a written requirements document)\n\n- [ ] Are clauses cited by ID when answered?\n- [ ] Is source language quoted verbatim where intent matters?\n- [ ] Are explicit statements distinguished from implied or assumed requirements?\n- [ ] Are silent, ambiguous, or self-contradictory areas of the source flagged?\n\n### Understanding And Contextualization\n\n- [ ] Is there a customer-primary glossary (definitions first; Rocket notes only where needed)?\n- [ ] Where one customer term hides multiple platform patterns, are splits in glossary (or rare concept_unification), not duplicated 1:1 mappings?\n- [ ] Where one customer term hides multiple platform patterns, are the patterns split and named?\n- [ ] Are platform capability claims verified against the CRM Knowledge MCP and the local repo?\n- [ ] Are external dependencies (APIs, partners, regulations) reality-checked before being promised?\n- [ ] Are \"asked for\" and \"offered beyond\" capabilities clearly distinguished?\n\n### Structuring\n\n- [ ] Does vocabulary alignment lead the document, before any feature walkthrough?\n- [ ] Do peer modules use the same subsection scaffold?\n- [ ] Do major sections close with a compressed implementation matrix where useful?\n- [ ] Is data ownership and integration architecture placed in a single section and referenced?\n- [ ] Where capabilities ship in stages, is the proposal sequenced by delivery phase?\n- [ ] For requirements-driven proposals, does each requirement carry a fit status (Supported / Partial / New Development)?\n\n### Writing — Core Structure\n\n- [ ] Did you apply `CORE_WRITING_PRINCIPLES.md` before drafting?\n- [ ] Does each section lead with an overview before detail?\n- [ ] Are peer sections grouped by one dimension?\n- [ ] Are sections MECE for the scope promised?\n- [ ] Are flat lists kept at the same abstraction level?\n\n### Writing — Platform Visibility\n\n- [ ] Does every section describe what the system does, not only what it enables?\n- [ ] Are features presented through journey walkthroughs?\n- [ ] Are claims replaced with specific behavior, scope, examples, numbers, or limits?\n- [ ] Do diagrams mirror the text instead of adding a second, disconnected story?\n\n### Writing — Options And Trade-Offs\n\n- [ ] Are real implementation choices shown as options?\n- [ ] Are trade-off dimensions relevant to the buyer?\n- [ ] Is the recommendation stated clearly?\n- [ ] Does the reasoning reference the trade-off table?\n\n### Writing — Proposal Scope\n\n- [ ] Are all touchpoints, flows, channels, and operational roles covered?\n- [ ] Are cross-cutting concerns handled across every relevant channel?\n- [ ] Are dependencies cross-referenced instead of duplicated?\n- [ ] Are unsupported, rare, risky, or fallback scenarios stated?\n\n### Writing — Voice And Authenticity\n\n- [ ] Does the writing sound like a systems architect, not a salesperson?\n- [ ] Are filler phrases removed?\n- [ ] Are section lengths allowed to vary based on real complexity?\n- [ ] Are headings phrased as the reader's natural question where it helps orientation?\n- [ ] Are flexibility claims anchored with a worked example in the customer's context?\n- [ ] Would a technical evaluator think \"they have actually built this\"?", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#proposal-quality-checklist", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "proposal-quality-checklist", "parent_section": "Section 4 — Writing", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "cd49c950746773308827715cab7cf740fda6e9a168c0b170675e8f8027b17813", "truncated": false}, "is_active": true}, {"id": "8a3f221e-1c99-5ffb-873a-3ba74760b697", "feature_slug": "proposal-writing", "title": "Proposal Writing — Overview", "content": "**When to use:** B2B proposals, RFP responses, SOWs. R/U/S/W framework: read requirements, understand context, structure, write sections.\n**Source:** `PROPOSAL_WRITING_PRINCIPLES.md`\n**Genre:** `proposal`\n\nReading, Understanding, Structuring, And Writing For B2B SaaS Platform Proposals", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "overview", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "6117136451adf34e5fd2d58c114e5a1baad323e81eb6374be18d28e4b9c2a7fd", "truncated": false}, "is_active": true}, {"id": "777321ee-9c37-5f2d-b7a5-56a505821249", "feature_slug": "proposal-writing", "title": "Purpose", "content": "These principles govern B2B SaaS platform proposals: how to read customer requirements, how to interpret them against the platform, how to organize the response, and how to write each section so it sounds like someone who has actually built the platform.\n\nUse `CORE_WRITING_PRINCIPLES.md` first for the shared structural rules:\n\n- Pyramid structure.\n- Vertical logic.\n- Horizontal logic.\n- MECE grouping.\n- Same-level abstraction.\n- Parallel peer points.\n- Layered depth.\n- Specificity and explicit limitations.\n\nThis document explains how those principles apply specifically to proposals, plus proposal-only practices for reading source material, understanding what was asked, structuring the response, and writing each section.\n\nA proposal succeeds when:\n\n1. The reader sees exactly how their operation works on the platform.\n2. Every section shows a distinct part of the system, with no overlaps or obvious gaps.\n3. The writing sounds like an experienced systems architect walking through a whiteboard, not a salesperson reciting benefits.\n\nThe four sections below run in the order the work happens: read the source, interpret it, organize the response, then write each section.\n\n---", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#purpose", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "purpose", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "c27b4bdddb4ca62b4acbc82a6cb9958096b6f77cb7f42597c5949fa318f4c4de", "truncated": false}, "is_active": true}, {"id": "c76aa2d2-3a29-5dff-901b-bdffb76839a1", "feature_slug": "proposal-writing", "title": "R1. Cite Source Clauses By ID When You Answer Them", "content": "When a section answers a specific clause in the requirements document, cite the clause ID. This lets the buyer trace your interpretation back to their words and verify coverage section by section.\n\nExample:\n\n> The TOR explicitly states (B3.4): \"การเข้าใช้บริการ 'แพ็กเกจหลายครั้ง/คูปองชุด' และการสร้าง/ตัดอัตโนมัติ หลัง ซื้อ/เข้ารับบริการ\" — auto-create and auto-deduct after purchase/service via HIS API.\n\n> The TOR says (C2): \"ซื้อ Membership หรือ Subsciption Plan เช่น Divine Elite\" and \"ใช้ payment gateway ฝั่ง Rocket ทั้งหมด end to end.\"", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#r1-cite-source-clauses-by-id-when-you-answer-them", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "r1-cite-source-clauses-by-id-when-you-answer-them", "parent_section": "Section 1 — Reading Customer Requirements", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "a3f81fa51ac611677d4223b7678a047f0314955b87533b67779613de106e9f1a", "truncated": false}, "is_active": true}, {"id": "271c4048-4959-5524-b2c5-4d1531b941b6", "feature_slug": "proposal-writing", "title": "R2. Quote Source Language Verbatim When Intent Matters", "content": "Paraphrase flattens nuance the customer chose deliberately, especially in non-English source documents where translation choices change meaning. Quote verbatim, then translate or interpret next to it.\n\nExample:\n\n> The TOR (C5.6): \"การใช้สิทธิ์ร่วม/ไม่ร่วม กับ Coins/eCoupon/ส่วนลดอื่น (stackability / precedence).\" This means: some health packages allow insurance discount + coin discount together, others don't.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#r2-quote-source-language-verbatim-when-intent-matters", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "r2-quote-source-language-verbatim-when-intent-matters", "parent_section": "Section 1 — Reading Customer Requirements", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "7720c8c71aa1fe883ec0b87a5728cfdfebbb39041b04e4427c1fe94be7d209c0", "truncated": false}, "is_active": true}, {"id": "63447266-ab78-5430-9743-029a42e00d1d", "feature_slug": "proposal-writing", "title": "R3. Distinguish Explicit Statements From Implied Or Assumed Requirements", "content": "Implied requirements are interpretations and should be marked as such. Stating an assumption gives the customer a chance to confirm or correct before the assumption is baked into a delivery plan.\n\nExample:\n\n> The TOR mentions missions generically — does NOT specifically request milestone (multi-level) missions.\n\n> The TOR does NOT explicitly specify a primary key for user matching. In the Thai hospital context, the most likely approach... This should be clarified with Samitivej's tech team during technical design.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#r3-distinguish-explicit-statements-from-implied-or-assumed-requirements", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "r3-distinguish-explicit-statements-from-implied-or-assumed-requirements", "parent_section": "Section 1 — Reading Customer Requirements", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "cbb2ebc12024ce414bc4bfbd8284b9a1cfa2d8bab22c53e2bf1546e02588b25f", "truncated": false}, "is_active": true}, {"id": "1cc3c68e-41d6-55bb-9600-1db77ec7fcaf", "feature_slug": "proposal-writing", "title": "R4. Note Where The Source Is Silent, Ambiguous, Or Self-Contradictory", "content": "Silent and contradictory areas are scope risks. Identifying them up front is the difference between a thoughtful response and a default-yes response that explodes during execution.\n\nExample:\n\n> The TOR references Coins only — no mention of \"Tickets\" or multiple currency types.\n\n> The TOR says two things that must be read together: F3 ... and A2.6 ... This means the data has two layers.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#r4-note-where-the-source-is-silent-ambiguous-or-self-contradictory", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "r4-note-where-the-source-is-silent-ambiguous-or-self-contradictory", "parent_section": "Section 1 — Reading Customer Requirements", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "425e104baa8cbe4aa7772d7f163b815a5e5036b7e8bad991a2f215d6a94b57a2", "truncated": false}, "is_active": true}, {"id": "9be3a00f-9095-566a-aa06-d523774c9279", "feature_slug": "proposal-writing", "title": "S1. Lead With Vocabulary Alignment Before Any Feature Walkthrough", "content": "Place a **customer-primary glossary** at the front of the document, before any feature or journey content. Without this front-load, the reader fights vocabulary mismatch through every later section. A separate concept-unification chapter is **optional** and only for 1:many splits that do not fit inside the glossary.\n\nExample document order:\n\n```\nGlossary of terms (customer definitions + optional Rocket notes)\n    -> [Optional] Concept splits only when one customer term maps to multiple constructs\n        -> Phase 1 requirements (body uses customer vocabulary)\n            -> Phase 2 requirements\n                -> Feature mapping summary\n                    -> Pages, demo scenarios, data architecture, timeline\n```", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#s1-lead-with-vocabulary-alignment-before-any-feature-walkthrough", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "s1-lead-with-vocabulary-alignment-before-any-feature-walkthrough", "parent_section": "Section 3 — Structuring The Proposal", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "10c8f8ff83e8151f7757f21a9bf0f5b15c742addb14c92423ddac5a8f4dc23c0", "truncated": false}, "is_active": true}, {"id": "6c0d74f1-02a0-5b79-beb9-ca658d1e376e", "feature_slug": "proposal-writing", "title": "S2. Use The Same Subsection Scaffold Across Peer Modules", "content": "When the proposal walks through N peer items (touchpoints, features, modules), use an identical subsection structure for each. Same headings, same order — even if some items end up shorter because they are genuinely simpler.\n\nRepeated structure trains the reader to scan. It also makes gaps visible: if one module skips a section that all others have, that signals either a missing piece or a real difference in the underlying capability.\n\nExample (every feature module follows the same scaffold):\n\n```\na) Core Concepts & Definitions\nb) Full Capabilities\nc) Marketer View\nd) Technical View\ne) Implementation Examples (Customer-specific)\n```\n\nExample (every touchpoint covers the same dimensions):\n\n```\nIntegration architecture\n    -> Customer journey\n        -> Options when multiple paths exist\n            -> Security and fraud risk\n                -> Recommended path with reasoning\n```", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#s2-use-the-same-subsection-scaffold-across-peer-modules", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "s2-use-the-same-subsection-scaffold-across-peer-modules", "parent_section": "Section 3 — Structuring The Proposal", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "c3915f25ca5e10dc7e1f335ac0420ae7dcf9d8c89d1bb8c74cc9315f198c3697", "truncated": false}, "is_active": true}, {"id": "1f81e0ea-b8ee-5df7-896a-db6d68e4efe6", "feature_slug": "proposal-writing", "title": "S3. Close Major Sections With A Compressed Implementation Matrix", "content": "End major sections with a single matrix that compresses everything across consistent dimensions. Same dimensions across all rows.\n\nExecutives and architects need a one-screen view of the surface area after the detailed walkthrough. Uneven complexity across rows becomes visible — that is a feature, not a bug.\n\nExample:\n\n| Touchpoint | Method | Integration Type | Security Level | Real-time | Fraud Risk | Strategic Requirements |\n|---|---|---|---|---|---|---|\n| Fuel Stations | POS/EDC Direct Integration | Existing API (Enhancing) | High | Yes | Low | System upgrade in progress |\n| Merchant On-us | Acquirer Integration (EDC) | Caltex MID Terminal | Very High | Yes | None | Acquirer partnership, device deployment |\n| Merchant On-us | Caltex POS System | Full POS replacement | Medium | Yes | Medium | Strategic POS rollout decision |", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#s3-close-major-sections-with-a-compressed-implementation-matrix", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "s3-close-major-sections-with-a-compressed-implementation-matrix", "parent_section": "Section 3 — Structuring The Proposal", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "4141b9487fed4a98dad4b6eaf01178bda4d94f687a066b12bf56ce1049a197a2", "truncated": false}, "is_active": true}, {"id": "a1a5698b-0f18-53e7-8bc7-7c9d7f30fd18", "feature_slug": "proposal-writing", "title": "S4. Place Data Ownership And Integration Architecture In One Section, Then Reference", "content": "For integration-heavy proposals, put the source-of-truth map and integration diagram in one dedicated section. Reference it from feature sections instead of restating ownership inside each feature walkthrough.\n\nWithout a single map, downstream sections drift between systems and the buyer cannot tell who owns each record. Repeating the ownership story per feature also bloats the document.\n\nExample (one source-of-truth table referenced throughout):\n\n| Data Type | Source of Truth | Who Creates | Who Reads | Notes |\n|---|---|---|---|---|\n| Medical service catalog | CDP Hospital | Hospital team | Our system consumes catalog | We mainly need the catalog, not necessarily real-time prices |\n| Health Packages | Our system | Marketing team in our back office | Well app, website, LINE, HIS | We determine price |\n| Entitlement records | Our system | Auto-issued on purchase | Patient (app), staff (admin), HIS (via API) | All changes flow through our system |", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#s4-place-data-ownership-and-integration-architecture-in-one-section-then-reference", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "s4-place-data-ownership-and-integration-architecture-in-one-section-then-reference", "parent_section": "Section 3 — Structuring The Proposal", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "3a270bf070cd973936a8eff572160ec134396cea50fc96ffa8af86e0c979ece4", "truncated": false}, "is_active": true}, {"id": "48cff578-0473-5897-bec0-978feabb5fb2", "feature_slug": "proposal-writing", "title": "S5. Sequence Features By Delivery Phase When Capabilities Ship In Stages", "content": "When some capabilities ship at launch and others ship later, sequence the proposal by phase rather than mixing phases inside feature sections. Make each phase's go-live deliverable clear.\n\nPhase-based sequencing matches how the buyer's program governance, budget release, and acceptance testing actually work. It also keeps \"we will build this someday\" language out of the day-one scope.\n\nExample structure:\n\n```\nSection 3 — Phase 1 Requirements\nSection 4 — Phase 2 Requirements\nSection 5 — Phase 3 Requirements\nSection 6 — Consolidated Mapping Summary Across All Phases\nSection 7+ — Project plan with Go-Live #1 and Go-Live #2 dates\n```", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#s5-sequence-features-by-delivery-phase-when-capabilities-ship-in-stages", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "s5-sequence-features-by-delivery-phase-when-capabilities-ship-in-stages", "parent_section": "Section 3 — Structuring The Proposal", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "34f25f19386fc799d0c00559212a83f16d1cb48f8198e20dc221f21c899901d5", "truncated": false}, "is_active": true}, {"id": "865661fe-3c72-59a6-9c90-41f44fd339c9", "feature_slug": "proposal-writing", "title": "S6. Tag Each Requirement With A Fit Status — Conditional", "content": "**Conditional.** Apply when the proposal walks the customer's enumerated requirements one by one (TOR-response, RFP-response, requirements-CSV-response).\n\nFor each requirement, give a one-word fit status — **Supported**, **Partial**, or **Not Yet Built / New Development** — followed by what exists, what needs enhancement, and what is brand new.\n\nBuyers reading a long requirements-mapped proposal need to scan for risk. Fit status lets them locate the unsupported and partially supported areas without inferring scope from feature descriptions.\n\nExample (fully supported) — customer-facing; no schema or requirement codes:\n\n> | Requirement | Coverage | Notes |\n> |---|---|---|\n> | Member wallet balance and full earn/burn history | Supported | Points and tickets; delayed earn when rules require it |\n> | Tier-based earn multipliers | Supported | Configured in admin; evaluated on each qualifying purchase |\n\nExample (not built):\n\n> | Requirement | Coverage | Notes |\n> |---|---|---|\n> | Multi-step journey automation with A/B branches | New development | SMS channel exists; journey builder not in current product |\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#s6-tag-each-requirement-with-a-fit-status-conditional", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "s6-tag-each-requirement-with-a-fit-status-conditional", "parent_section": "Section 3 — Structuring The Proposal", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "0e0859d66d1e49653562b73851e953fd67fa904b66cbe61d9011a5c73f743586", "truncated": false}, "is_active": true}, {"id": "ce84717a-352d-5cff-8cfc-c49dec8f39f2", "feature_slug": "proposal-writing", "title": "Sources", "content": "- `CORE_WRITING_PRINCIPLES.md` — pyramid structure, vertical logic, horizontal logic, MECE, same-level abstraction, layered depth, specificity, and explicit limitations.\n- `.cursor/rules/15-crm-knowledge.mdc` — CRM Knowledge MCP retrieval workflow used by U3 to verify platform capability claims.\n- Barbara Minto, *The Minto Pyramid Principle* — top-down structure, SCQA, vertical logic, horizontal logic, and MECE grouping.\n- Style reference: Caltex Thailand Loyalty Platform Proposal — journey walkthrough pattern, options with trade-offs, layered depth, explicit limitations, systems architect voice, repeated subsection scaffold, closing implementation matrix, and worked-example anchoring.\n- Style reference: Samitivej Loyalty Program Requirement Analysis — source clause citation, verbatim quoting of source language, vocabulary bridge and concept unification, pattern splitting (Pattern A vs Pattern B), reality-checking external APIs and commercial dependencies, fit-status tagging per requirement, source-of-truth data map, phase-based sequencing, and reader-question headings.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#sources", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "sources", "parent_section": "Section 4 — Writing", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "49ab18b1d47eabfda970b8f9f0002d5b895a7593c267a470681e07362fc5f0f8", "truncated": false}, "is_active": true}, {"id": "d1c01d45-d6aa-5d05-a100-f517024c1a1f", "feature_slug": "proposal-writing", "title": "U1. Build A Vocabulary Bridge Between Customer Terms And Platform Terms", "content": "When the customer uses terms that overlap with but do not exactly match the platform's terms, build an explicit mapping early. Do not silently swap one term for the other. Do not force the platform to adopt the customer's word without saying so.\n\nPattern:\n\n```\nGlossary of customer terms (definition in their framing; Rocket note only when needed)\n    -> Optional Concept splits subsection when one customer word hides multiple platform patterns\n        -> Body uses customer terms throughout; Rocket names in integration + notes only\n```\n\nExample (glossary Rocket CRM note when rename is needed):\n\n| Customer term | Definition | Rocket CRM note |\n|---|---|---|\n| eVoucher (TOR) | Digital benefit delivered by code | Configured as digital reward with promo code pool |\n\nExample (legacy separate concept table — use only for large splits, not 1:1 duplicates):\n\n| Samitivej Concept | Our Reward Configuration |\n|---|---|\n| eCoupon (single-use) | Reward with `fulfillment = digital`, quantity = 1, promo code attached |\n| Mandatory Coupon | Reward with `visibility = admin`, auto-issued on package purchase via API |\n| Seasonal Coupon | Reward with `visibility = campaign`, trigger = birthday/anniversary |\n\nExample (naming clarification stated explicitly):\n\n> The RFP uses \"eVoucher\" terminology, but we refer to this as \"stored value card\" to distinguish from reward vouchers that may also be electronic.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#u1-build-a-vocabulary-bridge-between-customer-terms-and-platform-terms", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "u1-build-a-vocabulary-bridge-between-customer-terms-and-platform-terms", "parent_section": "Section 2 — Understanding And Contextualizing Requirements", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "79d6a5ba7d787d10e5a0172cb9b7d02b1fc97d7b4ca3b0688d8f93681f207aa3", "truncated": false}, "is_active": true}, {"id": "109526e9-853c-53e4-ae7c-a680af681499", "feature_slug": "proposal-writing", "title": "U2. Recognize When One Customer Term Hides Multiple Platform Patterns", "content": "Customers often bundle distinct concepts under one word. When you spot this, split the concept and name each pattern separately. Map each pattern to its own platform construct.\n\nCollapsing two patterns into one mapping hides a real architectural decision and usually leads to under-scoping the new development or building the wrong thing.\n\nExample:\n\n> Samitivej's entitlement system has two fundamentally different patterns:\n>\n> Pattern A: Consumable items → Our Reward\n> These are items that get \"used up\" — single-use coupons, multi-use packages with a count, one-time vouchers.\n>\n> Pattern B: Standing benefits → New concept (Benefit Rules)\n> These are ongoing membership benefits that NEVER get consumed — they apply every time the member uses a service, for the entire validity period.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#u2-recognize-when-one-customer-term-hides-multiple-platform-patterns", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "u2-recognize-when-one-customer-term-hides-multiple-platform-patterns", "parent_section": "Section 2 — Understanding And Contextualizing Requirements", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "03451e0a7be68be1c3b749ad83cbe3cf5b0b69ff4e4b5602f4456174a5082e26", "truncated": false}, "is_active": true}, {"id": "80ae7411-f044-5989-ba40-a3db3bfdb918", "feature_slug": "proposal-writing", "title": "U3. Reality-Check Customer Assumptions Before Agreeing They Are Feasible", "content": "When a request rests on an assumption that may not hold (a public API exists, a partner will integrate, a workflow is industry-standard, the platform supports something), pause and verify. State the finding. Then offer a realistic alternative.\n\nVerification checklist:\n\n| Assumption type | How to verify |\n|---|---|\n| Platform capability claim (ours) | Query the CRM Knowledge MCP per `.cursor/rules/15-crm-knowledge.mdc` and verify against the local repo. Do not promise a capability that has not been validated this way. |\n| External API or integration | Read the actual API documentation. Check whether the endpoint is public, partner-only, or requires a B2B agreement. |\n| Partner cooperation | Identify whether the partner has a known program for this integration, or whether a new commercial agreement is required. |\n| Regulatory or compliance requirement | Identify the specific regulation (PDPA, e-money, AML) and whether it affects feasibility or timeline. |\n| Workflow assumption | Name the assumption and ask whether it holds in the customer's specific environment. |\n\nPattern:\n\n```\nReality Check — X\n    -> findings on each component\n        -> What This Means for [Customer]\n            -> realistic alternative path\n```\n\nExample:\n\n> Reality Check — Platform Coin Transfer APIs:\n> - Shopee Coins: No public API exists for transferring Shopee Coins to external loyalty programs ... A direct coin transfer would require a B2B commercial partnership.\n> - The1 (Central Group): Does support partner point exchange ... but works via a B2B commercial agreement, not a public endpoint.\n>\n> What This Means for Samitivej:\n> The coin transfer feature is technically straightforward on our side ... The blocker is commercial — each marketplace/partner requires a business development deal.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#u3-reality-check-customer-assumptions-before-agreeing-they-are-feasible", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "u3-reality-check-customer-assumptions-before-agreeing-they-are-feasible", "parent_section": "Section 2 — Understanding And Contextualizing Requirements", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "ede84bbf8bf179249704688ca79c19e2bcf83b0f9f2e1f72acff97c42732edeb", "truncated": false}, "is_active": true}, {"id": "ae22933d-00b4-532c-889e-fabee0d6fbfc", "feature_slug": "proposal-writing", "title": "U4. Distinguish What The Customer Asked For From What You Are Offering Beyond", "content": "Label requested capabilities and bonus capabilities differently at the section level. Make the distinction visible per requirement, not just in a final scope table.\n\nBuyers comparing vendors need to verify scope coverage without filtering out your bonus features. Mixing the two inflates perceived complexity and makes apples-to-apples comparison hard.\n\nExample (repeated per requirement section):\n\n> What the TOR Specifies:\n> - Display current coin balance\n> - Full earn/burn/expire history\n> - Omni-channel wallet\n>\n> Additional Capabilities We Offer (beyond TOR):\n> - Multiple currency types (Coins + Tickets)\n> - Delayed award (24h hold before wallet credit)\n> - Reversal/cancellation for refunds\n\nA top-of-document note that lists the major \"our extras, NOT in the source requirements\" also helps buyers know what to discount when comparing scope across vendors.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#u4-distinguish-what-the-customer-asked-for-from-what-you-are-offering-beyond", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "u4-distinguish-what-the-customer-asked-for-from-what-you-are-offering-beyond", "parent_section": "Section 2 — Understanding And Contextualizing Requirements", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "7be54712046e741ec8df7fe5fdedf93e67211369e271a0d0ef5317dca7de6988", "truncated": false}, "is_active": true}, {"id": "a75bc27f-3c1c-5202-b43d-6619a702e325", "feature_slug": "proposal-writing", "title": "W1. Show The Platform, Do Not Argue For It", "content": "The proposal's job is to make the platform visible: how data moves, how users interact, how systems connect, what operators control, and where the limits are.\n\nIt is not a pitch deck. It should not lean on ROI claims, industry benchmarks, or generic arguments that loyalty programs are valuable. In an RFP or serious platform evaluation, the reader already accepts the category. They need to understand what the system will do.\n\nWeak:\n\n> Tiered loyalty programs increase customer lifetime value.\n\nStronger:\n\n> The platform supports three tier levels. Each tier has configurable earn rates, benefit packages, and auto-upgrade rules based on spend thresholds.\n\nWeak:\n\n> Real-time processing improves customer satisfaction.\n\nStronger:\n\n> Points calculate and return in under one second. The EDC prints the earned points on the receipt before the customer leaves the counter.\n\nTest: if the sentence still works after replacing Rocket with a competitor name, it is probably a claim. Rewrite it as specific system behavior.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#w1-show-the-platform-do-not-argue-for-it", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "w1-show-the-platform-do-not-argue-for-it", "parent_section": "Section 4 — Writing", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "bc0129a887cb2989c4eb01426ba906cae4bed0044af3900f1b4ad5734a8be0da", "truncated": false}, "is_active": true}, {"id": "e5d4463e-9ecf-5998-a704-e245ed8b18fa", "feature_slug": "proposal-writing", "title": "W10. Write In A Systems Architect Voice", "content": "The default proposal voice is someone who has built the system, deployed it, and watched real users interact with it.\n\n| Trait | What it sounds like |\n|---|---|\n| Shows the system | Describes user actions, data flows, system responses, and operator controls |\n| Knows edge cases | Names what does not work, what is rare, and what needs a workaround |\n| Gives honest assessments | States security risk, setup complexity, operational burden, and trade-offs |\n| Uses grounded evidence | Cites field research, existing infrastructure, actual flow constraints, or implementation facts |\n| Recommends with reasoning | Chooses an option and explains why using the comparison dimensions |\n\nAvoid proposal voice that sounds like a generic vendor:\n\n| Weak | Stronger |\n|---|---|\n| Our platform enables a seamless customer experience | The customer sees earned points on the receipt before leaving the counter |\n| Comprehensive reporting gives visibility | The portal shows points issued, rewards redeemed, transaction history, and campaign performance by date and location |\n| Robust integration with existing systems | The POS sends transactions through RabbitMQ middleware to Rocket's earn API |\n| Flexible campaign management | Marketers build campaigns by combining actions, conditions, and outcomes without developer support |", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#w10-write-in-a-systems-architect-voice", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "w10-write-in-a-systems-architect-voice", "parent_section": "Section 4 — Writing", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "362568d18477dbe4deebd417149bce2bb192a74f66fb76f16edda19fc6ed9dfb", "truncated": false}, "is_active": true}, {"id": "4d78e204-9158-52a0-94db-81f291303651", "feature_slug": "proposal-writing", "title": "W11. Let Structure Signal Authenticity", "content": "Proposal structure itself tells the reader whether the writer understands the system.\n\nAuthentic proposal structure:\n\n- Section lengths vary based on real system complexity.\n- \"Not available\" and \"not recommended\" scenarios appear where relevant.\n- Comparison tables show uneven options when one option is clearly better.\n- Notes and caveats clarify likely reader confusion.\n- Numbers are specific when known and qualified when uncertain.\n- Constraints sit next to capabilities instead of being hidden later.\n\nAvoid artificial balance. Real systems are uneven.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#w11-let-structure-signal-authenticity", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "w11-let-structure-signal-authenticity", "parent_section": "Section 4 — Writing", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "17d97f3eb5312107c51c2e79d5d3e984b331c69e17c10b709d238e90eeffe400", "truncated": false}, "is_active": true}, {"id": "853e4767-5dc4-5bbf-bbd3-7e301b4d70e1", "feature_slug": "proposal-writing", "title": "W12. Headings: Descriptive Noun Phrase by Default, Question When It's a Decision", "content": "The default heading style for a proposal subsection is a **descriptive noun phrase** that names the topic — this reads as a professional consulting document.\n\nExamples of correct default style:\n\n- Earn process: division of responsibility\n- Reward catalogue: inventory sources and availability\n- Admin portal: what the operator sees day-to-day\n- Currency engine: scope and headroom\n\nUse a **question heading only when** the subheading marks a genuine decision-point the reader has come to the document to resolve — ownership disputes, conditional branching, configuration options with real trade-offs:\n\n- Who Deducts — HIS or Our Admin?\n- What Happens if Package Details Change?\n- Where Does the Purchase Happen?\n- Which earn channels need middleware vs direct API?\n\nQuestion headings are not decorative. \"What can the points engine do?\" is not a decision-point — the reader isn't choosing whether to use the engine, they're reading to understand it. Use \"Points engine: scope and headroom\" instead.\n\n**Section-level colon subtitles:** a colon subtitle is useful only when it meaningfully sharpens the contract. \"Tier Programme: member-facing mechanics\" works. \"Integration Architecture: Connecting {Customer}'s Back-End to Rocket CRM\" should be simplified to either \"Integration Architecture\" or \"Back-End Integration: key flows\". Customer and vendor names belong in the body, not in section titles — they add noise to the TOC without adding information.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#w12-headings-descriptive-noun-phrase-by-default-question-when-it-s-a-decision", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "w12-headings-descriptive-noun-phrase-by-default-question-when-it-s-a-decision", "parent_section": "Section 4 — Writing", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "9c05ee3cedde5eee8fdbdfabef0df5cfa731ff4ca4fe12a9c81a3a25a190c052", "truncated": false}, "is_active": true}, {"id": "4252d28f-b6c5-5b97-89c2-ef300867dd10", "feature_slug": "proposal-writing", "title": "W13. Anchor Flexibility Claims With A Worked Example In The Customer's Context", "content": "When describing a configurable or composable system, show one concrete trip through it: real customer, real product, real timestamps, real numbers resolving to a single output. The example must use the customer's domain — their products, their tiers, their personas, their venues — not a generic placeholder.\n\n\"Flexible\" is a low-evidence claim. A worked example proves the system can resolve a realistic input to a deterministic, explainable output. Using the customer's own context proves you have thought about how their real transactions would land on the system.\n\nExample (Caltex multi-currency earn — uses Caltex products, stations, tiers):\n\n> Transaction: Gold member buys 40L Power D at Highway station, 7 AM Monday, pays with Starcash\n>\n> Applicable Earn Factors:\n> 1. Base Rate: 1L = 1 point\n> 2. Gold Tier Factor: 1.5x\n> 3. Power D Premium: 1.2x\n> 4. Highway Bonus: 1.3x\n> 5. Morning Rush: 1.4x\n> 6. Starcash Payment: +10 fixed points\n>\n> Calculation (multiplicative stacking):\n> - Base: 40 points\n> - With factors: 40 × 1.5 × 1.2 × 1.3 × 1.4 = 131 points\n> - Plus fixed: 131 + 10 = 141 total points\n\nA generic \"Customer X buys product Y\" example would not have done the same work.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#w13-anchor-flexibility-claims-with-a-worked-example-in-the-customer-s-context", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "w13-anchor-flexibility-claims-with-a-worked-example-in-the-customer-s-context", "parent_section": "Section 4 — Writing", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "23c11fbfb33e9b7c0f80ee0b377b08906032c740f329eed2324db2a40189d8cc", "truncated": false}, "is_active": true}, {"id": "53b9603f-3238-5765-89d3-c5572cf4c377", "feature_slug": "proposal-writing", "title": "W14. Section Titles: Describe the Business Outcome", "content": "A section title describes what the customer is buying for their business in the fewest words that remain specific.\n\n**Rules:**\n- Name the business outcome, not the product catalog category. \"Trading-linked loyalty earning\" beats \"API Earning\". \"Member reward redemption\" beats \"Burning\".\n- Colon subtitles are fine when they sharpen the contract. \"Tier Programme: member-facing mechanics\" is appropriate. \"Integration Architecture: Connecting {Customer}'s Back-End to Rocket CRM\" should be trimmed — it combines two ideas; pick the specific one.\n- Customer names and vendor names belong in the body, not in section titles. They add noise to the TOC without adding information to a reader scanning for what's covered.\n- Avoid long verb phrases as titles. \"How Rocket CRM handles earn-rate calculation\" is a heading for a wiki article, not a proposal section — use \"Earn-rate calculation: how it works\" or simply \"Earn-rate calculation\".\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#w14-section-titles-describe-the-business-outcome", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "w14-section-titles-describe-the-business-outcome", "parent_section": "Section 4 — Writing", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "b546d6734e7192e55b01f5651d9e2e7c831b411c110076c247394ff447738881", "truncated": false}, "is_active": true}]$seed_json$::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
